{
  "restricciones": [
    {
      "id": "R1",
      "cumple": true,
      "evidencia": "Se adopta un estilo monolito modular construido con FastAPI sobre Python 3.12"
    },
    {
      "id": "R2",
      "cumple": true,
      "evidencia": "La base de datos PostgreSQL existente es la única base de datos; No se introducen otras bases"
    },
    {
      "id": "R3",
      "cumple": true,
      "evidencia": "Sin colas ni brokers de mensajes; se usa APScheduler in‑process"
    },
    {
      "id": "R4",
      "cumple": true,
      "evidencia": "Los correos se envían solo mediante el servicio interno existente: POST /internal/mail/send"
    },
    {
      "id": "R5",
      "cumple": true,
      "evidencia": "La detección de bajas de precio se ejecuta como tarea programada cada hora dentro de la misma aplicación"
    },
    {
      "id": "R6",
      "cumple": true,
      "evidencia": "No se contratan ni integran servicios de terceros nuevos"
    }
  ],
  "specs": [
    {
      "id": "SPEC-01",
      "cubierto": true,
      "evidencia": "Endpoint /wishlist/add (ARCH-01) llama a ARCH-02.add_wishlist que valida duplicados, límite 50 y guarda saved_price vía ARCH-04 y ARCH-03"
    },
    {
      "id": "SPEC-02",
      "cubierto": true,
      "evidencia": "Endpoint /wishlist/remove (ARCH-01) llama a ARCH-02.remove_wishlist; si no existe lanza ItemNotFoundError → 400 Bad Request (ítem no encontrado)"
    },
    {
      "id": "SPEC-03",
      "cubierto": true,
      "evidencia": "GET /wishlist (ARCH-01) devuelve items con saved_price y current_price; ARCH-02.get_wishlist_with_current obtiene current_price mediante ARCH-04"
    },
    {
      "id": "SPEC-04",
      "cubierto": true,
      "evidencia": "ARCH-05 Price Detection Scheduler ejecuta cada hora, consulta precio actual vía ARCH-04 y compara con saved_price para detectar bajas ≥ umbral (default 10 %)"
    },
    {
      "id": "SPEC-05",
      "cubierto": true,
      "evidencia": "ARCH-05 llama a ARCH-06.NotificationService que envía correo vía POST /internal/mail/send y actualiza last_notified, respetando máximo 1 aviso cada 24 h"
    },
    {
      "id": "SPEC-06",
      "cubierto": true,
      "evidencia": "ARCH-07 Auth Middleware devuelve 401/403 con {enabled:false, message:\"Inicia sesión para usar tu lista de deseos\"}; también endpoint /wishlist/status (ARCH-01)"
    }
  ],
  "funcionalidades_inventadas": [],
  "datos_inventados": [],
  "contratos_completos": true,
  "puntaje_revision": 9,
  "justificacion": "La arquitectura cumple todas las restricciones y cubre cada requerimiento especificado con contratos claros; solo falta explícita garantía de ordenamiento en la consulta, pero es menor."
}
